use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn contains(self, x: int) -> bool {
        let mut n = self.root
        while n >= 0 {
            let k = self.keys[n]
            if x == k {
                return true
            }
            if x < k {
                n = self.lefts[n]
            } else {
                n = self.rights[n]
            }
        }
        false
    }

    fn insert(self, x: int) {
        let id = self.keys.len() as int
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root < 0 {
            self.root = id
            return
        }
        let mut n = self.root
        loop {
            if x < self.keys[n] {
                if self.lefts[n] < 0 {
                    self.lefts[n] = id
                    return
                }
                n = self.lefts[n]
            } else {
                if self.rights[n] < 0 {
                    self.rights[n] = id
                    return
                }
                n = self.rights[n]
            }
        }
    }

    fn del(self, n: int, x: int) -> int {
        if n < 0 {
            return -1
        }
        let k = self.keys[n]
        if x < k {
            let r = self.del(self.lefts[n], x)
            self.lefts[n] = r
            return n
        }
        if x > k {
            let r = self.del(self.rights[n], x)
            self.rights[n] = r
            return n
        }
        if self.lefts[n] < 0 {
            return self.rights[n]
        }
        if self.rights[n] < 0 {
            return self.lefts[n]
        }
        let mut s = self.rights[n]
        while self.lefts[s] >= 0 {
            s = self.lefts[s]
        }
        let sk = self.keys[s]
        self.keys[n] = sk
        let r = self.del(self.rights[n], sk)
        self.rights[n] = r
        n
    }

    fn height(self, n: int) -> int {
        if n < 0 {
            return 0
        }
        let a = self.height(self.lefts[n])
        let b = self.height(self.rights[n])
        if a > b { a + 1 } else { b + 1 }
    }

    fn walk(self, n: int, out: Vec<string>) {
        if n < 0 {
            return
        }
        self.walk(self.lefts[n], out)
        out.push("${self.keys[n]}")
        self.walk(self.rights[n], out)
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 {
            x = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if t.contains(x) {
                println("dup")
            } else {
                t.insert(x)
                println("ok")
            }
        } else if cmd == "contains" {
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.contains(x) {
                let r = t.del(t.root, x)
                t.root = r
                println("ok")
            } else {
                println("missing")
            }
        } else if cmd == "inorder" {
            let mut out: Vec<string> = []
            t.walk(t.root, out)
            if out.len() == 0 { println("<empty>") } else { println(out.join(" ")) }
        } else if cmd == "height" {
            println("${t.height(t.root)}")
        } else if cmd == "min" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut n = t.root
                while t.lefts[n] >= 0 {
                    n = t.lefts[n]
                }
                println("${t.keys[n]}")
            }
        } else if cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut n = t.root
                while t.rights[n] >= 0 {
                    n = t.rights[n]
                }
                println("${t.keys[n]}")
            }
        }
    }
}

